/**
 * One quote of QuoteSplit: a QuoteCard with the author's picture and the stars, as a card or a plain figure, in
 * a box that can span grid rows.
 */
import { type ReactNode } from "react";
import { Box } from "../compose";
import { QuoteCard } from "../components/quote-card";
import type { Quote, QuoteLabels } from "../blocks/testimonial-grid.types";

export type QuoteSlotProps = {
  q: Quote;
  labels: QuoteLabels;
  kind?: "card" | "plain";
  layout?: "grid" | "single" | "stack";
  className?: string;
};

export function QuoteSlot({ q, labels, kind = "card", layout = "grid", className }: QuoteSlotProps) {
  return (
    <Box className={className} data-slot="quote">
      <QuoteCard q={q} labels={labels} item={{ kind, avatar: "image", rating: "show", mark: "none" }} layout={layout} />
    </Box>
  );
}
